using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct GoalId : IEquatable<GoalId>, IComparable<GoalId>
    {
        public Guid Value { get; }

        public GoalId(Guid value)
        {
            Value = value;
        }

        public static GoalId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static GoalId NewRandom() => new GoalId(Guid.NewGuid());

        public static GoalId Parse(string text) => new GoalId(Guid.Parse(text));

        public static bool TryParse(string text, out GoalId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new GoalId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(GoalId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is GoalId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(GoalId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(GoalId left, GoalId right) => left.Equals(right);

        public static bool operator !=(GoalId left, GoalId right) => !left.Equals(right);
    }
}
